          var own = dv && typeof dv === 'object' && 'href' in dv ? dv.href : undefined;
          var link = own !== undefined ? own : href && hrefSkip.indexOf(st) < 0 ? href.replace('{date}', iso) : null;
          out.push(link ? '<a href="' + esc(link) + '">' + mark + '</a>' : mark);
