      var style = 'left:' + left + '%;width:' + r2(w) + '%;--c:' + (s.color || 'var(--cb-accent)') + ';' + (ink ? '--ink:' + ink + ';--ink-shadow:transparent;' : '') +
        (kind === 'events' ? 'top:' + top + ';height:' + rowH + 'px' : 'top:' + r2(fr[0] * 100) + '%;bottom:' + r2((1 - fr[1]) * 100) + '%');
      var tip = (s.tip || s.label || '') + (s.label || s.tip ? ' · ' : '') + fmt.hhmm(s.start) + '–' + fmt.hhmm(s.end) + ' (' + fmt.min(s.end - s.start) + ')' +
        (s.state && s.state !== 'observed' ? ' · ' + CB.prov.LABELS[s.state] : '');
