      var tag = s.href ? 'a' : 'div';
      out.push('<' + tag + (s.href ? ' href="' + esc(s.href) + '"' : '') + ' class="cb-tl-seg ' + CB.prov.cls(s.state) + '" style="' + style + '" data-tip="' + esc(tip) + '">' + lbl + '</' + tag + '>');
