        var tip = (p.tip || p.label || '') + ' · ' + fmt.hhmm(col.t0) + '–' + fmt.hhmm(col.t1) + ' · ' + fmt.min(p.v);
        return '<i class="' + CB.prov.cls(p.state) + '" style="height:' + r2(CB.clamp(p.v / cap, 0, 1) * 100) + '%;--c:' + p.color + '" data-tip="' + esc(tip) + '"></i>';
