      var hgt = l.height || (kind === 'thin' ? 12 : kind === 'columns' ? 56 : kind === 'events' ? rows * ((l.rowHeight || 16) + 2) + 2 : 34);
      return '<div style="height:' + hgt + 'px">' + esc(l.label || '') + '</div>';
