    square: function (c) { return '<rect class="f" x="3" y="3" width="8" height="8" style="fill:' + c + '"/>'; },
    ring: function (c) { return '<circle cx="7" cy="7" r="4.5" style="fill:none;stroke:' + c + ';stroke-width:1.6"/>'; },
    dashed: function (c) { return '<rect x="2.5" y="2.5" width="9" height="9" style="fill:none;stroke:' + c + ';stroke-width:1.4;stroke-dasharray:2.2 1.6"/>'; },
    line: function (c) { return '<line x1="1" y1="7" x2="13" y2="7" style="stroke:' + c + ';stroke-width:2.5;stroke-linecap:round"/>'; },
